def solve_linear(A: np.ndarray, b: np.ndarray) -> np.ndarray | None:
    if not is_invertible(A):
        return None
    return np.linalg.solve(A, b)

def is_invertible(A: np.ndarray) -> bool:
    try:
        return np.linalg.matrix_rank(A) == A.shape[0] and A.shape[0] == A.shape[1]
    except np.linalg.LinAlgError:
        return False

def check_solution(A: np.ndarray, b: np.ndarray, x: np.ndarray) -> float:
    diff = A @ x - b
    return float(np.max(np.abs(diff)))

