import numpy as np

def svd_decompose(A: np.ndarray) -> dict:
    U, s, Vt = np.linalg.svd(A, full_matrices=False)
    return {'U': U, 's': s, 'Vt': Vt}

def svd_compress(A: np.ndarray, k: int) -> np.ndarray:
    U, s, Vt = np.linalg.svd(A, full_matrices=False)
    return U[:, :k] @ np.diag(s[:k]) @ Vt[:k, :]

def compression_ratio(A: np.ndarray, k: int) -> float:
    m, n = A.shape
    return round(k * (m + n + 1) / (m * n), 4)

