def power_iteration(A: np.ndarray, iters: int = 100) -> dict:
    n = A.shape[0]
    v = np.ones(n) / np.sqrt(n)
    for _ in range(iters):
        Av = A @ v
        v = Av / np.linalg.norm(Av)
    eigenvalue = float(v @ (A @ v))
    return {'eigenvalue': round(eigenvalue, 4), 'eigenvector': v}

def page_rank(links: list, damping: float = 0.85, iters: int = 100) -> list:
    pages = set()
    for f, t in links:
        pages.add(f); pages.add(t)
    pages = sorted(pages)
    n = len(pages)
    idx = {p: i for i, p in enumerate(pages)}
    M = np.zeros((n, n))
    out_degree = np.zeros(n)
    for f, t in links:
        M[idx[t], idx[f]] += 1
        out_degree[idx[f]] += 1
    for j in range(n):
        if out_degree[j] > 0:
            M[:, j] /= out_degree[j]
        else:
            M[:, j] = 1.0 / n
    r = np.ones(n) / n
    for _ in range(iters):
        r = damping * (M @ r) + (1 - damping) * np.ones(n) / n
    result = [(pages[i], round(float(r[i]), 4)) for i in range(n)]
    result.sort(key=lambda x: -x[1])
    return result

import numpy as np

def train_naive_bayes(data: list[dict]) -> dict:
    classes = {}
    for d in data:
        lbl = d['label']
        if lbl not in classes:
            classes[lbl] = []
        classes[lbl].append(d['features'])
    n_total = len(data)
    priors = {}
    likelihoods = {}
    for lbl, samples in classes.items():
        priors[lbl] = len(samples) / n_total
        arr = np.array(samples)
        n_features = arr.shape[1]
        likelihoods[lbl] = {}
        for j in range(n_features):
            col = arr[:, j]
            total_ones = int(np.sum(col))
            total = len(col)
            likelihoods[lbl][j] = (total_ones + 1) / (total + 2)
    return {'priors': priors, 'likelihoods': likelihoods}

def predict(model: dict, features: list) -> str:
    best_label = None
    best_score = -float('inf')
    for lbl, prior in model['priors'].items():
        score = np.log(prior)
        for j, val in enumerate(features):
            p = model['likelihoods'][lbl][j]
            if val == 1:
                score += np.log(p)
            else:
                score += np.log(1 - p)
        if score > best_score:
            best_score = score
            best_label = lbl
    return best_label

