def negative_log_likelihood(data: np.ndarray, mu: float, sigma: float) -> float:
    n = len(data)
    if sigma <= 0:
        return float('inf')
    nll = n / 2 * np.log(2 * np.pi * sigma**2) + np.sum((data - mu)**2) / (2 * sigma**2)
    return round(float(nll), 4)

