import numpy as np

def numerical_gradient(f, x: np.ndarray, h: float = 1e-5) -> np.ndarray:
    grad = np.zeros_like(x)
    for i in range(len(x)):
        x_plus = x.copy()
        x_minus = x.copy()
        x_plus[i] += h
        x_minus[i] -= h
        grad[i] = (f(x_plus) - f(x_minus)) / (2 * h)
    return grad

def relative_error(num: np.ndarray, analytic: np.ndarray) -> float:
    denom = np.linalg.norm(num) + np.linalg.norm(analytic)
    if denom == 0:
        return 0.0
    return float(np.linalg.norm(num - analytic) / denom)

def check_gradient(f, grad_f, x: np.ndarray) -> dict:
    num = numerical_gradient(f, x)
    analytic = grad_f(x)
    err = relative_error(num, analytic)
    return {'max_relative_error': round(err, 8), 'pass': err < 1e-4}

